     7→import org.springframework.http.converter.HttpMessageNotReadableException;
     8→import org.springframework.web.bind.MethodArgumentNotValidException;
     9→import org.springframework.web.bind.MissingServletRequestParameterException;
    10→import org.springframework.web.bind.annotation.ExceptionHandler;
    11→import org.springframework.web.bind.annotation.RestControllerAdvice;
    12→import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
    13→
    14→import java.time.LocalDateTime;
    15→import java.util.stream.Collectors;
    16→
    17→@RestControllerAdvice
    18→@Log4j2
    19→public class GlobalExceptionHandler {
    20→
    21→    @ExceptionHandler(MethodArgumentNotValidException.class)
    22→    public ResponseEntity<ErrorResponse> handleValidationErrors(MethodArgumentNotValidException ex) {
    23→        String message = ex.getBindingResult().getFieldErrors().stream()
    24→                .map(e -> e.getField() + ": " + e.getDefaultMessage())
    25→                .collect(Collectors.joining(", "));
    26→        log.warn("Validation failed: {}", message);
    27→        return ResponseEntity.badRequest().body(ErrorResponse.builder()
    28→                .status(HttpStatus.BAD_REQUEST.value())
    29→                .message(message)
    30→                .timestamp(LocalDateTime.now())
    31→                .build());
    32→    }
    33→
    34→    @ExceptionHandler(MissingServletRequestParameterException.class)
    35→    public ResponseEntity<ErrorResponse> handleMissingParam(MissingServletRequestParameterException ex) {
    36→        log.warn("Missing request parameter: {}", ex.getParameterName());
    37→        return ResponseEntity.badRequest().body(ErrorResponse.builder()
    38→                .status(HttpStatus.BAD_REQUEST.value())
    39→                .message("Missing required parameter: " + ex.getParameterName())
    40→                .timestamp(LocalDateTime.now())
    41→                .build());
    42→    }
    43→
    44→    @ExceptionHandler(MethodArgumentTypeMismatchException.class)
    45→    public ResponseEntity<ErrorResponse> handleTypeMismatch(MethodArgumentTypeMismatchException ex) {
    46→        String message = String.format("Invalid value '%s' for parameter '%s'", ex.getValue(), ex.getName());
    47→        log.warn("Type mismatch: {}", message);
    48→        return ResponseEntity.badRequest().body(ErrorResponse.builder()
    49→                .status(HttpStatus.BAD_REQUEST.value())
    50→                .message(message)
    51→                .timestamp(LocalDateTime.now())
    52→                .build());
    53→    }
    54→
    55→    @ExceptionHandler(HttpMessageNotReadableException.class)
    56→    public ResponseEntity<ErrorResponse> handleUnreadableBody(HttpMessageNotReadableException ex) {
    57→        log.warn("Malformed request body: {}", ex.getMessage());
    58→        return ResponseEntity.badRequest().body(ErrorResponse.builder()
    59→                .status(HttpStatus.BAD_REQUEST.value())
    60→                .message("Malformed or missing request body")
    61→                .timestamp(LocalDateTime.now())
    62→                .build());
    63→    }
    64→
    65→    @ExceptionHandler(Exception.class)
    66→    public ResponseEntity<ErrorResponse> handleGeneral(Exception ex) {
    67→        log.error("Unhandled exception: {}", ex.getMessage(), ex);
    68→        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(ErrorResponse.builder()
    69→                .status(HttpStatus.INTERNAL_SERVER_ERROR.value())
    70→                .message("An unexpected error occurred")
    71→                .timestamp(LocalDateTime.now())
    72→                .build());
    73→    }
    74→}
