     1→package com.integration.security;
     2→
     3→import lombok.extern.log4j.Log4j2;
     4→import org.springframework.beans.factory.annotation.Value;
     5→import org.springframework.http.HttpStatus;
     6→import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
     7→import org.springframework.security.core.context.SecurityContextHolder;
     8→import org.springframework.stereotype.Component;
     9→import org.springframework.web.filter.OncePerRequestFilter;
    10→
    11→import javax.servlet.FilterChain;
    12→import javax.servlet.ServletException;
    13→import javax.servlet.http.HttpServletRequest;
    14→import javax.servlet.http.HttpServletResponse;
    15→import java.io.IOException;
    16→import java.util.Collections;
    17→
    18→@Component
    19→@Log4j2
    20→public class ApiKeyAuthFilter extends OncePerRequestFilter {
    21→
    22→    private static final String API_KEY_HEADER = "X-API-Key";
    23→
    24→    @Value("${api.key}")
    25→    private String validApiKey;
    26→
    27→    @Override
    28→    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
    29→                                    FilterChain filterChain) throws ServletException, IOException {
    30→        String providedKey = request.getHeader(API_KEY_HEADER);
    31→        if (validApiKey.equals(providedKey)) {
    32→            UsernamePasswordAuthenticationToken auth =
    33→                    new UsernamePasswordAuthenticationToken("api-key-user", null, Collections.emptyList());
    34→            SecurityContextHolder.getContext().setAuthentication(auth);
    35→            filterChain.doFilter(request, response);
    36→        } else {
    37→            log.warn("Unauthorized request to {} — invalid or missing API key", request.getRequestURI());
    38→            response.setStatus(HttpStatus.UNAUTHORIZED.value());
    39→            response.getWriter().write("Unauthorized");
    40→        }
    41→    }
    42→
    43→    @Override
    44→    protected boolean shouldNotFilter(HttpServletRequest request) {
    45→        String path = request.getRequestURI();
    46→        return path.startsWith("/webhook/");
    47→    }
    48→}
