   201→    @Override
   202→    public ResponseEntity<Object> fetchLeadById(String leadId) throws Exception {
   203→        String url = getUrl(lsqGetLeadByIdUrl) + "&id=" + leadId;
   204→        Map<String, String> headers = new HashMap<>();
   205→        headers.put("Content-Type", "application/json");
   206→        ResponseEntity responseEntity = restUtils.get(url, headers);
   207→
   208→        try {
   209→            if (responseEntity.getStatusCode() == HttpStatus.OK && responseEntity.getBody() != null) {
   210→                List<Map<String, Object>> responseList = (List<Map<String, Object>>) responseEntity.getBody();
   211→                if (responseList != null && !responseList.isEmpty()) {
   212→                    Map<String, Object> leadData = responseList.get(0);
   213→                    String prospectId = (String) leadData.get("ProspectID");
   214→
   215→                    Optional<LeadsquaredUser> existingUser = leadsquaredUserRepository.findById(prospectId);
   216→                    if (!existingUser.isPresent()) {
   217→                        LeadsquaredUser newUser = new LeadsquaredUser();
   218→                        newUser.setProspectId(prospectId);
   219→                        newUser.setOwner((String) leadData.get("OwnerIdName"));
   220→                        String firstName = leadData.get("FirstName") != null ? (String) leadData.get("FirstName") : "";
   221→                        String lastName = leadData.get("LastName") != null ? (String) leadData.get("LastName") : "";
   222→                        newUser.setFirstName((firstName).trim());
   223→                        newUser.setLastName((lastName).trim());
   224→                        newUser.setMobile((String) leadData.get("Phone"));
   225→
   226→                        String createdOnStr = (String) leadData.get("CreatedOn");
   227→                        if (createdOnStr != null) {
   228→                            DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
   229→                            newUser.setCreatedOn(dateFormat.parse(createdOnStr));
   230→                        }
   231→
   232→                        leadsquaredUserRepository.save(newUser);
