   309→    public boolean processLsqPaymentLinkActivity(Date fromDate, Date toDate) throws Exception {
   310→        String fetchActivitiesUrl = lsqActivityUrl;
   311→        Map<String, String> headers = createHeaders();
   312→        DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
   313→        String fromDateString = dateFormat.format(fromDate);
   314→        String toDateString = dateFormat.format(toDate);
   315→        int pageIndex = 1;
   316→        int pageSize = 500;
   317→        int processedRecords = 0;
   318→        int totalRecords = Integer.MAX_VALUE;
   319→        boolean success = true;
   320→        String prospectActivityId = null;
   321→        while (processedRecords < totalRecords) {
   322→            try {
   323→                String body = createActivityPayload(pageIndex, pageSize, fromDateString, toDateString, "212");
   324→                ResponseEntity<Map> r = restUtils.postV2(fetchActivitiesUrl, body, headers);
   325→
   326→                try{
   327→                    logApiCall("Payment Link Activity", fetchActivitiesUrl, body, r.getBody() != null ? r.getBody().toString() : "", r.getStatusCode().toString(), "LeadSquared");
   328→                }catch (Exception e){
   329→                    log.warn("Failed to log Payment Link Activity API call", e);
   330→                }
   331→                Map<String, Object> responseBody = r.getBody();
   332→
   333→                totalRecords = (int) responseBody.get("RecordCount");
   334→
   335→                if (responseBody != null) {
   336→                    List<Map<String, Object>> activityList = (List<Map<String, Object>>) responseBody.get("List");
   337→                    if (activityList != null) {
   338→                        for (Map<String, Object> activity : activityList) {
   339→                            try {
   340→                                processedRecords++;
   341→                                prospectActivityId = (String) activity.get("ProspectActivityId");
   342→                                LsqPaymentLinkActivity lsqPaymentLinkActivity = lsqPaymentLinkRepository.findByProspectActivityId(prospectActivityId);
   343→                                if(lsqPaymentLinkActivity==null){
   344→                                    lsqPaymentLinkActivity = new LsqPaymentLinkActivity();
   345→                                    lsqPaymentLinkActivity.setProspectActivityId(prospectActivityId);
   346→                                }
   347→                                lsqPaymentLinkActivity.setActivityEvent("212");
   348→                                lsqPaymentLinkActivity.setActivityEventName("Payment Link");
   349→                                lsqPaymentLinkActivity.setDisplayName("Payment Link");

